(6484116, 963389, 136232, '<td valign="top">I love the macro of raindrops and juxtaposition of flowers.</td>', 'I love the macro of raindrops and juxtaposition of flowers.', '2011-07-29 14:03:03.000000', NULL, 1),
(6484117, 963821, 136232, '<td valign="top">The light used at night gives an eerie effect.  The wood looks like it''s ready to come alive. Might''ve been neat to see a pair of eyes coming from the open doorway.</td>', 'The light used at night gives an eerie effect.  The wood looks like it''s ready to come alive. Might''ve been neat to see a pair of eyes coming from the open doorway.', '2011-07-29 14:03:09.000000', NULL, 1),
(6484118, 963760, 136232, '<td valign="top">I like the ephemeral quality to this piece.  I love the color pallet which combines hot yellow and oranges of the sunset with the cooler landscape and rocks.</td>', 'I like the ephemeral quality to this piece.  I love the color pallet which combines hot yellow and oranges of the sunset with the cooler landscape and rocks.', '2011-07-29 14:03:20.000000', NULL, 1),
(6484121, 963357, 136232, '<td valign="top">Nice starscape effect!  I would have liked the yellow light source to have been pointed at a different angle: either pointing up at the trees from directly below to follow the flow of movement of the stars, or lit from behind so it looks like one of the stars fell and lit up the earth.</td>', 'Nice starscape effect!  I would have liked the yellow light source to have been pointed at a different angle: either pointing up at the trees from directly below to follow the flow of movement of the stars, or lit from behind so it looks like one of the stars fell and lit up the earth.', '2011-07-29 14:03:24.000000', NULL, 1),
(6484122, 963824, 136232, '<td valign="top">Beautiful color composition: neon. Eye-catching.</td>', 'Beautiful color composition: neon. Eye-catching.', '2011-07-29 14:03:26.000000', NULL, 1),
(6484123, 963596, 136232, '<td valign="top">Beautiful pic of a face lit through blinds.  I''m not sure larger non-stripped shadow on the right edge of the face adds much to the overall composition.</td>', 'Beautiful pic of a face lit through blinds.  I''m not sure larger non-stripped shadow on the right edge of the face adds much to the overall composition.', '2011-07-29 14:03:28.000000', NULL, 1),
