(6486966, 963672, 104009, '<td valign="top">at least i wasn''t alone abotu the crop.  i hate leaving critical comments but i''m trying to leave more honestly and as kindly as i can.  i still think this was a great job.</td>', 'at least i wasn''t alone abotu the crop.  i hate leaving critical comments but i''m trying to leave more honestly and as kindly as i can.  i still think this was a great job.', '2011-08-01 13:25:53.000000', NULL, 0),
(6486968, 963585, 104009, '<td valign="top">im glad to see i wasn''t the only one "fooled" by the painting source, you did TOOOO well with it!  i''m sorry i didn''t give you further benefit of the doubt with this image it''s truly beautiful.</td>', 'im glad to see i wasn''t the only one "fooled" by the painting source, you did TOOOO well with it!  i''m sorry i didn''t give you further benefit of the doubt with this image it''s truly beautiful.', '2011-08-01 13:32:52.000000', NULL, 0),
(6487148, 963833, 68586, '<td valign="top">disappointing that this didn''t come higher - nice shot.</td>', 'disappointing that this didn''t come higher - nice shot.', '2011-08-01 15:21:43.000000', NULL, 0),
(6487448, 963656, 106806, '<td valign="top">not quite sure where the moving light is ... thats the trouble with challenges like this I guess unless its blindingly obvious ... leaving the challenge description aside though the headline title "Painting with light", well you sure as heck got that ...<br/> <br/>I really like this image and I think it captures what modern artistic photography is about ... I mean with modern cameras these days any old monkey can take a cool sharp well defined exposed image but not many people can produce something as artistic and as beautifull</td>', 'not quite sure where the moving light is ... thats the trouble with challenges like this I guess unless its blindingly obvious ... leaving the challenge description aside though the headline title "Painting with light", well you sure as heck got that ... I really like this image and I think it captures what modern artistic photography is about ... I mean with modern cameras these days any old monkey can take a cool sharp well defined exposed image but not many people can produce something as artistic and as beautifull', '2011-08-01 18:25:58.000000', NULL, 0),
(6487543, 963656, 10523, '<td valign="top">best in the challenge IMHO</td>', 'best in the challenge IMHO', '2011-08-01 19:36:25.000000', NULL, 0),
